from pathlib import Path

ROOT = Path('.')

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected 1 occurrence, got {count}')
    return text.replace(old, new, 1)

# index.html
path = ROOT / 'index.html'
text = path.read_text()
text = replace_once(text, '''          <label class="uw-habit-icon-field" title="그룹"><span aria-hidden="true">◉</span><select id="habitPageGroup" aria-label="습관 그룹"></select></label>\n          <label class="uw-habit-duration-field"><span>길이</span><select id="habitPageDuration" aria-label="습관 길이"><option value="30">30분</option><option value="60">1시간</option><option value="90">1시간 30분</option><option value="120">2시간</option></select></label>''', '''          <label class="uw-habit-icon-field" title="그룹"><span aria-hidden="true">◉</span><select id="habitPageGroup" aria-label="습관 그룹"></select></label>\n          <label class="uw-habit-range-field"><span>시작</span><input id="habitPageStartDate" type="date" aria-label="습관 시작일" /></label>\n          <label class="uw-habit-range-field"><span>종료</span><input id="habitPageEndDate" type="date" aria-label="습관 종료일" /></label>\n          <label class="uw-habit-duration-field"><span>길이</span><select id="habitPageDuration" aria-label="습관 길이"><option value="30">30분</option><option value="60">1시간</option><option value="90">1시간 30분</option><option value="120">2시간</option></select></label>''', 'habit add date fields')
text = text.replace('css/unified-workspace.css?v=28', 'css/unified-workspace.css?v=29', 1)
text = text.replace('js/unified-workspace.js?v=29', 'js/unified-workspace.js?v=30', 1)
path.write_text(text)

# unified-workspace.js
